// Navbar.jsx
import { NavLink } from "react-router-dom";
import styled from "styled-components";
import { useState, useEffect } from "react";

// --- Styled Components ---
const Nav = styled.nav`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 80px; /* wider navbar */
  height: 70px;
  background: linear-gradient(90deg, #2c2c2c, #1e1e1e); /* softer dark gradient */
  border-bottom: 1px solid #333;
  position: sticky;
  top: 0;
  z-index: 100;
`;

const LinksWrapper = styled.div`
  display: flex;
  gap: 40px;
  align-items: center;
`;

const StyledLink = styled(NavLink)`
  color: white;
  text-decoration: none;
  font-size: 18px;
  font-weight: 500;
  padding: 10px 15px;
  border-radius: 5px;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  height: 100%;

  &:hover {
    background-color: #e50914;
    color: #fff;
    transform: translateY(-2px);
  }

  &.active {
    color: #e50914;
    font-weight: 600;
    background-color: transparent;
    border-bottom: 3px solid #e50914;
  }
`;

const DarkModeButton = styled.button`
  padding: 6px 12px;
  font-size: 14px;
  background-color: #e50914;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.25s ease;

  &:hover {
    background-color: #ff1a2d;
  }
`;

// --- Navbar Component ---
const Navbar = () => {
  const [darkMode, setDarkMode] = useState(false);

  const toggleDarkMode = () => {
    setDarkMode(prev => !prev);
    document.body.style.background = !darkMode ? "#1e1e1e" : "#f5f5f5"; // dark gray for night mode
    document.body.style.color = !darkMode ? "#e0e0e0" : "#121212"; // soft text color
  };

  useEffect(() => {
    // initialize dark mode based on current body background
    const isDark = document.body.style.background === "rgb(30, 30, 30)";
    setDarkMode(isDark);
  }, []);

  return (
    <Nav>
      <div style={{ fontSize: "1.5rem", fontWeight: "700", color: "#e50914" }}>
        MyBooks
      </div>
      <LinksWrapper>
        <StyledLink to="/">Home</StyledLink>
        <StyledLink to="/books">All Books</StyledLink>
        <StyledLink to="/add">Add Book</StyledLink>
        <StyledLink to="/mybooks">My Books</StyledLink>
        <StyledLink to="/about">About</StyledLink>
        <DarkModeButton onClick={toggleDarkMode}>
          {darkMode ? "☀️" : "🌙"}
        </DarkModeButton>
      </LinksWrapper>
    </Nav>
  );
};

export default Navbar;
